def sgd_step(w, c_pos, c_negs, eta):
    g_pos, g_negs, g_w = sgns_gradients(w, c_pos, c_negs)    # all with the old values
    return w - eta * g_w, c_pos - eta * g_pos, [c - eta * g for c, g in zip(c_negs, g_negs)]

